-- 001_init.sql — initial schema for the codeindex / codemcp system.
-- Forward-only. Do not edit this file after it has been applied; create a new
-- migration script instead. The runner verifies the checksum on every run.

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS commits (
    commit_sha    TEXT PRIMARY KEY,
    branch        TEXT NOT NULL,
    indexed_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    embed_model   TEXT NOT NULL,
    embed_dim     INTEGER NOT NULL,
    file_count    INTEGER NOT NULL,
    chunk_count   INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS commits_branch_idx ON commits (branch, indexed_at DESC);

CREATE TABLE IF NOT EXISTS chunks (
    id             BIGSERIAL PRIMARY KEY,
    commit_sha     TEXT NOT NULL REFERENCES commits(commit_sha) ON DELETE CASCADE,
    path           TEXT NOT NULL,
    area           TEXT NOT NULL,
    language       TEXT NOT NULL,
    kind           TEXT NOT NULL,
    symbol         TEXT,
    parent_symbol  TEXT,
    start_line     INTEGER NOT NULL,
    end_line       INTEGER NOT NULL,
    content        TEXT NOT NULL,
    content_hash   TEXT NOT NULL,
    imports        TEXT[] NOT NULL DEFAULT '{}',
    claude_md      TEXT[] NOT NULL DEFAULT '{}',
    embedding      vector(768) NOT NULL
);

CREATE INDEX IF NOT EXISTS chunks_commit_idx     ON chunks (commit_sha);
CREATE INDEX IF NOT EXISTS chunks_path_idx       ON chunks (commit_sha, path);
CREATE INDEX IF NOT EXISTS chunks_symbol_idx     ON chunks (commit_sha, symbol);
CREATE INDEX IF NOT EXISTS chunks_area_idx       ON chunks (commit_sha, area);
CREATE INDEX IF NOT EXISTS chunks_kind_idx       ON chunks (commit_sha, kind);
CREATE INDEX IF NOT EXISTS chunks_hash_idx       ON chunks (content_hash);
CREATE INDEX IF NOT EXISTS chunks_embedding_hnsw
    ON chunks USING hnsw (embedding vector_cosine_ops);
